#!/usr/bin/env python3
"""
NeonGlyph Seamless Scaling Demonstration
Completely borderless, resizeable ASCII visuals that adapt perfectly to any monitor size
No OS chrome, no ASCII borders, pure seamless experience
"""

import os
import sys
import time
import random
import math
import threading
import queue
import ctypes
from ctypes import wintypes
import msvcrt
import subprocess

# Windows API constants
WS_POPUP = 0x80000000
WS_VISIBLE = 0x10000000
WS_EX_TOPMOST = 0x00000008
WS_EX_TOOLWINDOW = 0x00000080
SW_MAXIMIZE = 3
SW_SHOWMAXIMIZED = 3
GWL_STYLE = -16
GWL_EXSTYLE = -20
MONITOR_DEFAULTTOPRIMARY = 0x00000001

# Get console window handle
kernel32 = ctypes.windll.kernel32
user32 = ctypes.windll.user32

GetConsoleWindow = kernel32.GetConsoleWindow
GetConsoleWindow.restype = wintypes.HWND

GetWindowLongW = user32.GetWindowLongW
GetWindowLongW.argtypes = [wintypes.HWND, ctypes.c_int]
GetWindowLongW.restype = wintypes.LONG

SetWindowLongW = user32.SetWindowLongW
SetWindowLongW.argtypes = [wintypes.HWND, ctypes.c_int, wintypes.LONG]
SetWindowLongW.restype = wintypes.LONG

SetWindowPos = user32.SetWindowPos
SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_uint]
SetWindowPos.restype = wintypes.BOOL

ShowWindow = user32.ShowWindow
ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
ShowWindow.restype = wintypes.BOOL

GetSystemMetrics = user32.GetSystemMetrics
GetSystemMetrics.argtypes = [ctypes.c_int]
GetSystemMetrics.restype = ctypes.c_int

GetMonitorInfoW = user32.GetMonitorInfoW
GetMonitorInfoW.argtypes = [wintypes.HMONITOR, ctypes.c_void_p]
GetMonitorInfoW.restype = wintypes.BOOL

MonitorFromWindow = user32.MonitorFromWindow
MonitorFromWindow.argtypes = [wintypes.HWND, ctypes.c_uint]
MonitorFromWindow.restype = wintypes.HMONITOR

class RECT(ctypes.Structure):
    _fields_ = [("left", ctypes.c_long),
                ("top", ctypes.c_long),
                ("right", ctypes.c_long),
                ("bottom", ctypes.c_long)]

class MONITORINFO(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint),
                ("rcMonitor", RECT),
                ("rcWork", RECT),
                ("dwFlags", ctypes.c_uint)]

class NeonGlyphSeamless:
    def __init__(self):
        self.running = True
        self.audio_queue = queue.Queue()
        self.current_pattern = 0
        self.patterns = []
        self.frame_count = 0
        self.last_resize_check = 0
        self.console_width = 0
        self.console_height = 0
        self.monitor_width = 0
        self.monitor_height = 0
        self.console_hwnd = None
        self.is_seamless = False
        
        # Cyberpunk color palette
        self.colors = {
            'neon_cyan': '\033[36m',
            'neon_pink': '\033[35m',
            'neon_green': '\033[32m',
            'neon_yellow': '\033[33m',
            'bright_white': '\033[37m',
            'dim_white': '\033[90m',
            'reset': '\033[0m'
        }
        
        # Initialize seamless window
        self.setup_seamless_window()
        
        # Get monitor info
        self.get_monitor_dimensions()
        
        # Initialize patterns
        self.initialize_patterns()
        
        # Start audio simulation
        self.start_audio_simulation()
        
    def setup_seamless_window(self):
        """Remove ALL window borders and OS chrome for true seamless experience"""
        try:
            self.console_hwnd = GetConsoleWindow()
            if self.console_hwnd:
                # Remove ALL window styles for true borderless
                style = GetWindowLongW(self.console_hwnd, GWL_STYLE)
                style &= ~(0x00C00000 | 0x00080000 | 0x00040000 | 0x00020000 | 0x00010000)  # Remove all borders
                style |= WS_POPUP | WS_VISIBLE  # Minimal popup window
                SetWindowLongW(self.console_hwnd, GWL_STYLE, style)
                
                # Remove extended styles and set topmost
                ex_style = GetWindowLongW(self.console_hwnd, GWL_EXSTYLE)
                ex_style |= WS_EX_TOPMOST | WS_EX_TOOLWINDOW  # Hide from taskbar, stay topmost
                ex_style &= ~0x00040000  # Remove app window appearance
                SetWindowLongW(self.console_hwnd, GWL_EXSTYLE, ex_style)
                
                # Maximize to fill screen
                ShowWindow(self.console_hwnd, SW_MAXIMIZE)
                
                # Force window to front
                SetWindowPos(self.console_hwnd, -1, 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0020)  # SWP_NOSIZE | SWP_NOMOVE | SWP_FRAMECHANGED
                
                self.is_seamless = True
                print(f"{self.colors['neon_cyan']}Seamless window mode activated{self.colors['reset']}")
                
        except Exception as e:
            print(f"Window setup error: {e}")
            
    def get_monitor_dimensions(self):
        """Get primary monitor dimensions for perfect scaling"""
        try:
            # Get screen dimensions
            self.monitor_width = GetSystemMetrics(0)  # SM_CXSCREEN
            self.monitor_height = GetSystemMetrics(1)  # SM_CYSCREEN
            
            # Get console dimensions
            self.update_console_dimensions()
            
            print(f"Monitor: {self.monitor_width}x{self.monitor_height}")
            print(f"Console: {self.console_width}x{self.console_height}")
            
        except Exception as e:
            print(f"Monitor detection error: {e}")
            # Fallback dimensions
            self.monitor_width = 1920
            self.monitor_height = 1080
            self.console_width = 240
            self.console_height = 60
            
    def update_console_dimensions(self):
        """Update console buffer dimensions"""
        try:
            # Use mode command to get console size
            result = subprocess.run(['mode', 'con'], capture_output=True, text=True, shell=True)
            lines = result.stdout.split('\n')
            
            for line in lines:
                if 'Lines:' in line:
                    self.console_height = int(line.split(':')[1].strip())
                elif 'Columns:' in line:
                    self.console_width = int(line.split(':')[1].strip())
                    
        except:
            # Fallback dimensions
            self.console_width = 240
            self.console_height = 60
            
